import{z as d,x as A,o as s,c as B,q as l,j as i,D as E,d as e,s as n,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"调度指标","description":"","frontmatter":{"title":"调度指标","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scheduling-metrics.md","filePath":"cs/scheduling-metrics.md","lastUpdated":1791063341000}'),p={name:"cs/scheduling-metrics.md"};function m(c,a,h,D,u,C){const r=A("Mermaid");return s(),B("div",null,[a[2]||(a[2]=l('<h1 id="调度指标" tabindex="-1">调度指标 <a class="header-anchor" href="#调度指标" aria-label="Permalink to &quot;调度指标&quot;">​</a></h1><div class="epigraph"><p>调度算法的好坏取决于你先关心吞吐、等待、响应，还是公平；没有单一最优。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/idle-thread">上一课</a>让阻塞的调用能被唤醒，于是就绪队列里经常挤着多条线程。<a href="/cs/context-switch">上下文切换</a>已经能换谁上 CPU。缺口是：还没有尺子。本课只定义指标，不选时间片，也不引入公平调度器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「一直跑当前线程直到它退出」实现最简单，但短交互会被长计算挡住。反过来，切得太勤，切换本身吃掉吞吐。缺口不是再写一遍 PCB，而是先说清楚要优化什么：<strong>CPU 利用率、吞吐、周转时间、等待时间、响应时间</strong>，以及公平（相近的线程不应一个饿死）。<span class="marginnote">数字实例：作业 \\(t=0\\) 到达、\\(t=3\\) 首次上 CPU、\\(t=10\\) 完成、中间排队共 5 秒——周转 \\(=10-0=10\\)，响应 \\(=3-0=3\\)，等待 \\(=5\\)。三个数回答三个不同的问题：多久交付、多久有反应、多少时间白等。</span></p><p>实时期限是再下一课的对照；本课的对象是分时与批处理混在一起的通用指标。</p><p><span class="marginnote">周转 = 完成时刻 − 到达；等待 = 在就绪队列里的时间；响应 = 首次获得 CPU 的时刻 − 到达。三个量不是同一个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一组作业给出到达时间与 CPU 突发，按某策略模拟，算出上述均值。FCFS 的传送带效应、SJF 的短作业偏向、轮转的响应，都用同一套数字比较。本课不把证明「SJF 平均等待最优」写全，只锁定：换指标，名次就换。</p>',9)),(s(),i(o,null,{default:E(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOBS%5B%22%E5%88%B0%E8%BE%BE%E4%B8%8E%E7%AA%81%E5%8F%91%22%5D%20--%3E%20POL%5B%22%E8%B0%83%E5%BA%A6%E7%AD%96%E7%95%A5%22%5D%0A%20%20POL%20--%3E%20M%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%20%2F%20%E5%90%9E%E5%90%90%20%2F%20%E5%91%A8%E8%BD%AC%20%2F%20%E7%AD%89%E5%BE%85%20%2F%20%E5%93%8D%E5%BA%94%22%5D%0A%20%20M%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%3A%20%E6%97%B6%E9%97%B4%E7%89%87%E4%B8%8E%E5%85%AC%E5%B9%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("利用率与吞吐是系统视角；周转与响应是作业视角。公平不是均值能代替的：均值很好仍可有人饿死。"),t("span",{class:"marginnote"},"初学者容易把「平均周转短」当成调度器好，实际均值会掩盖饿死：让 99 个作业各周转 1 秒、1 个作业周转 1000 秒，均值仍然漂亮——公平必须单独考核，推不出来。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("指标让后课的时间片与权重有落点：缩短时间片通常改善响应、损害吞吐（切换变多）。下半部唤醒只是把线程放进就绪队列，"),t("strong",null,"不"),e("决定它何时跑；决定权在调度器，调度器按这些指标被评价。")],-1)),(s(),i(o,null,{default:E(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22t%3D0%20%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20W1%5B%22%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%E7%AD%89%E5%BE%85%22%5D%0A%20%20W1%20--%3E%20S%5B%22t%3D3%20%E9%A6%96%E6%AC%A1%E4%B8%8A%20CPU%3Cbr%2F%3E%E5%93%8D%E5%BA%94%20%3D%203%22%5D%0A%20%20S%20--%3E%20IO%5B%22t%3D5%20%E7%A3%81%E7%9B%98%E9%98%BB%E5%A1%9E%EF%BC%9A%E8%AE%A9%E5%87%BA%20CPU%22%5D%0A%20%20IO%20--%3E%20W2%5B%22%E9%87%8D%E6%96%B0%E6%8E%92%E9%98%9F%22%5D%0A%20%20W2%20--%3E%20S2%5B%22t%3D8%20%E6%81%A2%E5%A4%8D%E8%BF%90%E8%A1%8C%22%5D%0A%20%20S2%20--%3E%20F%5B%22t%3D10%20%E5%AE%8C%E6%88%90%3Cbr%2F%3E%E5%91%A8%E8%BD%AC%20%3D%2010%EF%BC%8C%E7%AD%89%E5%BE%85%20%3D%205%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">时间片的取舍可以类比红绿灯配时：绿灯给得太短（片太小），车刚起步就得停，路口空转（切换开销）吃掉通行量；给得太长，横向车流等到冒烟（响应变差）。指标的冲突，正是后课用虚拟运行时间做公平调度的起点。</span></p><p>I/O 与 CPU 突发交替：线程在磁盘上阻塞时，调度别人能提高利用率。这是中断下半部存在的调度理由，不是新的设备模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多核负载均衡、不把尾延迟当唯一指标，也不把「优先级反转」展开——那要锁。作业长度若未知，SJF 只能估计；本课承认估计误差，不把启发式写完。</p><p>实时对照课会换尺子：截止时间不是周转时间的别名，本课先不混用。</p><p>后课默认：谈到「调度得好」，必须先说哪一根尺子。通用分时如何用时间片与虚拟运行时间去逼近公平，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>就绪队列有人之后，先定义利用率、吞吐、周转、等待、响应与公平。</li><li>同一策略在不同指标下优劣会翻盘。</li><li>时间片与 CFS、实时调度都是后课用这些尺子去设计的。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const _=d(p,[["render",m]]);export{f as __pageData,_ as default};
